                innerPolygon.push_back(p);
            }
            innerPolygons.push_back(innerPolygon);
        }
    }

    ///TRIANGULATION

    internal::CDT cdt;
    cdt.insert_constraint(polygon1.vertices_begin(), polygon1.vertices_end(), true);
    for (unsigned int i = 0; i < innerPolygons.size(); ++i)
