            std::array<Point2d, 3> t;
            t[0] = Point2d(p1.x(), p1.y());
            t[1] = Point2d(p2.x(), p2.y());
            t[2] = Point2d(p3.x(), p3.y());
            triangles.push_back(t);
        }
    }
    return triangles;
}

